#!/usr/bin/env python3
"""Add Launchpad's task-specific guidance to a prompt. Generated by CodeRig — regenerate with `coderig connect`.

Run by the agent's prompt hook with --agent <name> (Claude Code and Codex UserPromptSubmit, Gemini
CLI BeforeAgent): reads the hook event on stdin and adds the guidance to that turn, in the agent's
own format (hookio.py). Fails open: any problem leaves the prompt as it is, and the developer is
told once per session that no guidance was fetched.
"""
import json
import os
import subprocess
import sys
import urllib.request
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent))
import hookio  # noqa: E402  (generated next to this file)

LAUNCHPAD = os.getenv("CODERIG_LAUNCHPAD", "http://localhost:8000").rstrip("/")
WORKSPACE = "proj-d9b4cf"
TIMEOUT = 5
CONNECT = "coderig connect --launchpad http://localhost:8000 --workspace proj-d9b4cf --agents copilot  (or Connect agents in the CodeRig app)"
ROOT = Path(__file__).resolve().parent.parent
STATE = ROOT / ".coderig" / "state" / "guide.json"


def git(*args):
    try:
        return subprocess.run(["git", "-C", str(ROOT), *args], capture_output=True, text=True,
                              timeout=5).stdout.strip()
    except Exception:
        return ""


def role():
    # The role Launchpad gave this developer when they connected; never one the session states.
    try:
        return hookio.role() or "developer"
    except Exception:
        return "developer"


def sent(session):
    try:
        return set(json.loads(STATE.read_text(encoding="utf-8")).get(session) or [])
    except Exception:
        return set()


def remember(session, skills):
    try:
        state = json.loads(STATE.read_text(encoding="utf-8")) if STATE.exists() else {}
        state[session] = sorted(set(state.get(session) or []) | set(skills))
        # one entry per session is enough to stop repeats; keep the file small
        state = dict(list(state.items())[-20:])
        STATE.parent.mkdir(parents=True, exist_ok=True)
        STATE.write_text(json.dumps(state), encoding="utf-8")
    except Exception:
        pass


def installed_sensors():
    # Launchpad names the ones that check the guidance at finish only when they are really installed here.
    try:
        config = json.loads((ROOT / ".coderig" / "sensors.json").read_text(encoding="utf-8"))
        return [s["id"] for s in config.get("sensors") or [] if isinstance(s, dict) and s.get("id")][:50]
    except Exception:
        return []


def unavailable(agent, session, why):
    """Guidance could not be fetched: the prompt goes ahead, and the developer hears so once per session."""
    marker = "!unavailable"
    if agent == "codex" or (session and marker in sent(session)):
        return 0  # Codex's prompt hook prints to the model, not to the developer
    if session:
        remember(session, [marker])
    return hookio.notice(agent, f"CodeRig could not fetch Launchpad's guidance for this task ({why}). "
                                "The prompt went ahead without it; the finish-time checks still run.")


def main():
    agent = hookio.agent()
    event = hookio.read_event()
    # A checkout nobody connected on this machine: no session until its developer does.
    if not hookio.connected():
        return hookio.refuse_prompt(agent, hookio.not_connected(CONNECT))
    if agent in ("cursor", "copilot"):
        return 0  # their prompt hook cannot add guidance; the check above is all it is for
    prompt = event["prompt"].strip()
    session = event["session"]
    if not prompt or prompt.startswith("/"):
        return  # a slash command carries its own instructions
    changed = git("diff", "--name-only", "HEAD").splitlines() + \
        git("ls-files", "--others", "--exclude-standard").splitlines()
    body = {"prompt": prompt[:8000], "changed_files": changed[:200],
            "branch": git("rev-parse", "--abbrev-ref", "HEAD") or None,
            "role": role(), "session_id": session or None, "sensors": installed_sensors()}
    request = urllib.request.Request(
        f"{LAUNCHPAD}/api/v1/workspace/{WORKSPACE}/guide", data=json.dumps(body).encode(),
        method="POST", headers={"Content-Type": "application/json"})
    try:
        with urllib.request.urlopen(request, timeout=TIMEOUT) as response:
            answer = json.loads(response.read() or b"{}")
    except Exception as exc:
        return unavailable(agent, session, type(exc).__name__)
    if not isinstance(answer, dict):
        return unavailable(agent, session, "an answer it could not read")
    skills = [s for s in answer.get("skills") or [] if isinstance(s, str)]
    guidance = answer.get("guidance")
    if not isinstance(guidance, str) or not guidance.strip() or not skills:
        return
    if session and set(skills) <= sent(session):
        return  # already given in this session
    if session:
        remember(session, skills)
    hookio.inject(agent, guidance)


if __name__ == "__main__":
    code = 0
    try:
        code = main() or 0
    except Exception:
        code = 0  # guidance fails open
    sys.exit(code)
